// config/race.json is the only editable source; generated files keep Vercel's og/ root self-contained.
import { readFile, writeFile } from 'node:fs/promises';
import assert from 'node:assert/strict';
const root=new URL('../../',import.meta.url);
const config=JSON.parse(await readFile(new URL('config/race.json',root),'utf8'));
const active=config.courses[config.activeCourse];
assert.ok(active);assert.equal(active.id,config.activeCourse);
assert.ok(Number.isInteger(config.boardRevision) && config.boardRevision>=config.minBoardRevision);
const pair=value=>assert.ok(Array.isArray(value) && value.length===2 && value.every(n=>Number.isFinite(n) && Math.abs(n)<=100000));
for(const [id,course] of Object.entries(config.courses)) {
  assert.match(id,/^[a-z][a-z0-9]{0,15}$/);pair(course.start);
  assert.ok(Number.isFinite(course.radius) && course.radius>0);
  assert.ok(Number.isFinite(course.vmax) && course.vmax>0);
  assert.ok(course.stops.length>0);
  course.stops.forEach(stop=>pair(Array.isArray(stop)?stop:stop.at));
}
assert.ok(Math.max(...active.physics.kmh)*active.physics.scale/3.6<=active.vmax,'遊戲極速不可超過伺服器上限');
const {physics,...race}=active;
const generated='// Generated by tools/build/race-config.mjs; edit config/race.json instead.\n'
  +'export const RACE = '+JSON.stringify(race,null,2)+';\n'
  +'export const PHYSICS = '+JSON.stringify(physics,null,2)+';\n'
  +'export const MIN_BOARD_REVISION = '+config.minBoardRevision+';\n';
const sqlURL=new URL('tools/leaderboard/supabase.sql',root);
const original=await readFile(sqlURL,'utf8');
const cases=Object.entries(config.courses).map(([id,c])=>{
  const value=JSON.stringify({start:c.start,radius:c.radius,vmax:c.vmax,stops:c.stops.map(s=>Array.isArray(s)?s:s.at)});
  return "    when '"+id+"' then '"+value+"'::jsonb";
}).join('\n');
const fn='create or replace function public.race_course(p_course text)\nreturns jsonb language sql immutable set search_path = public as $$\n  select case p_course\n'+cases+'\n  end\n$$;';
const functionPattern=/create or replace function public\.race_course\(p_course text\)[\s\S]*?\$\$;/;
assert.ok(functionPattern.test(original),'找不到路線 SQL 產生區塊');
const sql=original.replace(functionPattern,()=>fn).replace(/'rev', \d+,/,'\'rev\', '+config.boardRevision+',');
for(const [name,content] of [['3d/js/race-config.js',generated],['og/lib/race-config.js',generated],['tools/leaderboard/supabase.sql',sql]]) {
  const url=new URL(name,root);
  if(process.argv.includes('--check')) {
    const current=await readFile(url,'utf8').catch(()=> '');
    assert.equal(current.replaceAll('\r\n','\n'),content.replaceAll('\r\n','\n'),name+' 已過期，請重新產生設定');
  } else {await writeFile(url,content);console.log(name);}
}
